referenceSolutions.javascript:
export function solve(value) {
  const out = [];
  const visit = (v) => {
    if (Array.isArray(v)) for (const x of v) visit(x);
    else out.push(v);
  };
  visit(value);
  return out;
}

referenceSolutions.typescript:
export function solve(value: any[]): any {
  const out: any[] = [];
  const visit = (v: any): void => {
    if (Array.isArray(v)) for (const x of v) visit(x);
    else out.push(v);
  };
  visit(value);
  return out;
}
